<?php
namespace App\Services;
use App\Models\{UmkmDisbursement,UmkmDisbursementAllocation,UmkmDisbursementEvent,UmkmEntitlement,UmkmEntitlementEvent,UmkmStore,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;use Illuminate\Auth\Access\AuthorizationException;
class UmkmDisbursementFailureService {
 public function cancelRequested(UmkmDisbursement $d,User $u,string $reason):UmkmDisbursement{$this->owner($d,$u);return $this->release($d,$u,$reason,'cancelled','cancelled',['requested']);}
 public function recordTransferFailureEvidence(UmkmDisbursement $d,User $u,string $reason,string $reference,string $path):UmkmDisbursement{if($u->role!=='admin_bumdes')throw new AuthorizationException();if(blank(trim($reason))||blank(trim($reference))||blank($path))throw ValidationException::withMessages(['failure'=>'Alasan, referensi, dan bukti wajib.']);return $this->tx($d,function($x)use($u,$reason,$reference,$path){if($x->status!=='approved'||!$x->transfer_recorded_by||$x->paid_at)$this->bad('Bukti gagal belum dapat dicatat.');if($x->transfer_failure_recorded_by)return $x;$x->update(['transfer_failure_reason'=>trim($reason),'transfer_failure_proof_path'=>$path,'transfer_failure_recorded_by'=>$u->id,'transfer_failure_recorded_at'=>now(),'transfer_reference'=>trim($reference)]);$this->event($x,$u,'failure_evidence_recorded','approved','approved',$reason);return $x;});}
 public function confirmTransferFailure(UmkmDisbursement $d,User $u,string $confirmation):UmkmDisbursement{if($u->role!=='admin_bumdes'||blank(trim($confirmation)))throw new AuthorizationException();return $this->release($d,$u,$confirmation,'transfer_failed','transfer_failed',['approved'],true);}
 private function release($d,$u,$reason,$status,$event,$allowed,$failure=false){return $this->tx($d,function($x)use($u,$reason,$status,$event,$allowed,$failure){if($x->status===$status)return $x;if(!in_array($x->status,$allowed,true)||$x->paid_at||($status==='cancelled'&&$x->transfer_recorded_by)||($failure&&(!$x->transfer_failure_recorded_by||$x->transfer_failure_recorded_by===$u->id)))$this->bad('Release reservation tidak aman.');foreach(UmkmDisbursementAllocation::where('umkm_disbursement_id',$x->id)->orderBy('id')->lockForUpdate()->get() as $a){$e=UmkmEntitlement::whereKey($a->umkm_entitlement_id)->lockForUpdate()->firstOrFail();if($e->status!=='reserved')$this->bad('Entitlement tidak reserved.');$e->update(['status'=>'available']);$a->update(['entitlement_reservation_lock'=>null]);UmkmEntitlementEvent::firstOrCreate(['idempotency_key'=>$this->key('release',$e->id,$x->id)],['umkm_entitlement_id'=>$e->id,'actor_id'=>$u->id,'event_type'=>'reservation_released','amount'=>$a->amount,'from_status'=>'reserved','to_status'=>'available','notes'=>$reason]);}$x->update(['status'=>$status,'active_request_lock'=>null,'rejection_reason'=>$reason,'transfer_failure_verified_by'=>$failure?$u->id:null,'transfer_failure_verified_at'=>$failure?now():null]);$this->event($x,$u,$event,$allowed[0],$status,$reason);return $x;});}
 private function tx($d,$f){return DB::transaction(function()use($d,$f){UmkmStore::whereKey($d->umkm_store_id)->lockForUpdate()->firstOrFail();return $f(UmkmDisbursement::whereKey($d->id)->lockForUpdate()->firstOrFail());});}private function event($d,$u,$t,$f,$to,$n=null){UmkmDisbursementEvent::firstOrCreate(['idempotency_key'=>$this->key($t,$d->id,$d->id)],['umkm_disbursement_id'=>$d->id,'actor_id'=>$u->id,'event_type'=>$t,'from_status'=>$f,'to_status'=>$to,'notes'=>$n]);}private function key($t,$i,$s){$h=md5("fail:$t:$i:$s");return substr($h,0,8).'-'.substr($h,8,4).'-5'.substr($h,13,3).'-8'.substr($h,17,3).'-'.substr($h,20,12);}private function owner($d,$u){if($u->role!=='pemilik_umkm'||$d->umkmStore->user_id!==$u->id)throw new AuthorizationException();}private function bad($m):never{throw ValidationException::withMessages(['disbursement'=>$m]);}}
